def _set_cookies(response: Response, access: str, refresh: str) -> None:
    s = get_settings()
    common = {
        "httponly": True,
        "secure": s.cookie_secure,
        "samesite": s.cookie_samesite,
        "domain": s.cookie_domain,
    }
    response.set_cookie(ACCESS_COOKIE, access, max_age=s.access_token_minutes * 60, path=API_PATH, **common)
    response.set_cookie(REFRESH_COOKIE, refresh, max_age=s.refresh_token_days * 86400, path=AUTH_PATH, **common)


def _clear_cookies(response: Response) -> None:
    s = get_settings()
    for name, path in ((ACCESS_COOKIE, API_PATH), (REFRESH_COOKIE, AUTH_PATH)):
        response.delete_cookie(name, path=path, domain=s.cookie_domain)


