"use client";

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { Minus, Plus } from "lucide-react";
import Link from "next/link";
import { useState } from "react";
import { toast } from "sonner";
import { PageHeader } from "@/components/admin/page-header";
import { EmptyState, ErrorState, LoadingRows } from "@/components/admin/query-state";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { adjustInventory, listProducts, setInventory } from "@/services/admin";
import type { Variant } from "@/types/api";

export function StockEditor({ variant, label }: { variant: Variant; label?: string }) {
  const queryClient = useQueryClient();
  const inv = variant.inventory;
  const [value, setValue] = useState(String(inv?.quantity ?? 0));
  const refresh = () => {
    queryClient.invalidateQueries({ queryKey: ["products"] });
    queryClient.invalidateQueries({ queryKey: ["product"] });
    queryClient.invalidateQueries({ queryKey: ["low-stock"] });
    queryClient.invalidateQueries({ queryKey: ["summary"] });
  };
  const onError = (e: Error) => {
    toast.error(e.message);
    setValue(String(inv?.quantity ?? 0));
  };
  const set = useMutation({
    mutationFn: (q: number) => setInventory(variant.id, q),
    onSuccess: (v) => {
      toast.success("Stock updated");
      setValue(String(v.inventory?.quantity ?? 0));
      refresh();
    },
    onError,
  });
  const adjust = useMutation({
    mutationFn: (d: number) => adjustInventory(variant.id, d),
    onSuccess: (v) => {
      setValue(String(v.inventory?.quantity ?? 0));
      refresh();
    },
    onError,
  });
  const busy = set.isPending || adjust.isPending;
  const name = label ?? variant.weight;
  const parsed = Number(value);
  const valid = value.trim() !== "" && Number.isInteger(parsed) && parsed >= 0;

  return (
    <div className="flex flex-wrap items-center gap-2">
      <Button variant="outline" size="icon" disabled={busy || (inv?.quantity ?? 0) <= 0} aria-label={`Decrease stock of ${name}`} onClick={() => adjust.mutate(-1)}>
        <Minus />
      </Button>
      <Input
        type="number"
        min={0}
        inputMode="numeric"
        aria-label={`Stock quantity of ${name}`}
        className="h-8 w-20 text-center"
        value={value}
        onChange={(e) => setValue(e.target.value)}
        onKeyDown={(e) => e.key === "Enter" && valid && set.mutate(parsed)}
      />
      <Button variant="outline" size="icon" disabled={busy} aria-label={`Increase stock of ${name}`} onClick={() => adjust.mutate(1)}>
        <Plus />
      </Button>
      <Button size="sm" disabled={busy || !valid || parsed === inv?.quantity} onClick={() => set.mutate(parsed)}>
        Save
      </Button>
      {inv && inv.reserved > 0 && <span className="text-xs text-muted-foreground">{inv.reserved} reserved</span>}
    </div>
  );
}

export default function InventoryPage() {
  const [lowOnly, setLowOnly] = useState(false);
  const products = useQuery({
    queryKey: ["products", "inventory"],
    queryFn: () => listProducts({ status: "active", page_size: 100 }),
  });

  const rows =
    products.data?.items.flatMap((p) =>
      p.variants
        .filter((v) => v.is_active)
        .map((v) => ({ product: p, variant: v })),
    ) ?? [];
  const shown = lowOnly ? rows.filter((r) => r.variant.inventory && r.variant.inventory.available <= r.variant.inventory.low_stock_threshold) : rows;

  return (
    <>
      <PageHeader
        title="Inventory"
        description="Stock for every active variant. Use − / + for quick changes, or type a number and Save."
        actions={
          <Button variant={lowOnly ? "default" : "outline"} onClick={() => setLowOnly((v) => !v)} aria-pressed={lowOnly}>
            Low stock only
          </Button>
        }
      />
      {products.isPending ? (
        <LoadingRows />
      ) : products.isError ? (
        <ErrorState error={products.error} onRetry={() => products.refetch()} />
      ) : shown.length === 0 ? (
        <EmptyState
          title={lowOnly ? "Nothing is running low" : "No stock to manage yet"}
          hint={lowOnly ? undefined : "Add variants (250g / 500g / 1kg) to your active products first."}
        />
      ) : (
        <ul className="divide-y rounded-lg border bg-card">
          {shown.map(({ product, variant }) => {
            const inv = variant.inventory;
            const low = inv && inv.available <= inv.low_stock_threshold;
            return (
              <li key={variant.id} className="flex flex-wrap items-center gap-x-4 gap-y-2 p-3 sm:p-4">
                <div className="min-w-0 flex-1 basis-48">
                  <Link href={`/admin/products/${product.id}`} className="font-medium hover:underline">
                    {product.name}
                  </Link>
                  <div className="text-xs text-muted-foreground">{variant.weight}</div>
                </div>
                {low && <Badge variant={inv.available <= 0 ? "destructive" : "secondary"}>{inv.available <= 0 ? "Out of stock" : "Low"}</Badge>}
                <StockEditor variant={variant} label={`${product.name} ${variant.weight}`} />
              </li>
            );
          })}
        </ul>
      )}
    </>
  );
}
